// City totals describe the current networks; spare capacity cannot cross a break.
export const UTILITY_METRICS={powerUsagePercent:['Power supply used','%'],waterUsagePercent:['Water supply used','%'],powerDemand:['Power demand','units'],waterDemand:['Water demand','units'],powerAvailable:['Power available locally','units'],waterAvailable:['Water available locally','units'],powerUnserved:['Unserved power demand','units'],waterUnserved:['Unserved water demand','units']};
export function utilityTrendSnapshot(city){const s=city.stats,powerAvailable=s.powerNetworks.reduce((sum,g)=>sum+g.available,0),waterAvailable=s.waterCapacity;return{powerUsagePercent:powerAvailable?s.powerServed/powerAvailable*100:0,waterUsagePercent:waterAvailable?s.waterUsed/waterAvailable*100:0,powerDemand:s.powerDemand,waterDemand:s.waterDemand,powerAvailable,waterAvailable,powerUnserved:Math.max(0,s.powerDemand-s.powerServed),waterUnserved:Math.max(0,s.waterDemand-s.waterUsed)};}
export function utilityTrendReport(city){const d=utilityTrendSnapshot(city),fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:1});return `<details><summary>Utilities · supply usage and unmet demand</summary><p>Available supply includes current imports and subtracts exports. Usage is supply delivered locally divided by that available supply. When there is no supply, the recorded usage percentage is zero; check unserved demand to distinguish a blackout from an idle network.</p><div class="table-scroll"><table><thead><tr><th>Utility</th><th>Available</th><th>Demand</th><th>Supply used</th><th>Unserved demand</th></tr></thead><tbody>${['power','water'].map(k=>`<tr><td>${k==='power'?'Power':'Water'}</td><td>${fmt(d[k+'Available'])}</td><td>${fmt(d[k+'Demand'])}</td><td>${d[k+'Available']?fmt(d[k+'UsagePercent'])+'%':'No supply'}</td><td>${fmt(d[k+'Unserved'])}</td></tr>`).join('')}</tbody></table></div><p>These citywide totals cannot diagnose an individual network: disconnected neighborhoods may lack service while capacity elsewhere is unused. Water demand counts each lot once, even where pipe coverage overlaps. Inspect the Utilities report for local shortages.</p><div class="actions"><button id="reportPowerTrends">Compare power demand and supply</button><button id="reportWaterTrends">Compare water demand and supply</button><button id="reportUtilityUsage">Compare utility usage</button></div></details>`;}
